def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == color and (yy,xx) not in seen:
                        seen.add((yy,xx))
                        stack.append((yy,xx))
            r0, r1 = min(y for y,x in cells), max(y for y,x in cells)
            c0, c1 = min(x for y,x in cells), max(x for y,x in cells)
            comps.append((color, cells, r0, r1, c0, c1))

    # Objects are arranged in two rows in the result: objects originating in
    # the upper portion are moved to the top; lower objects to the bottom.
    # Preserve each object's horizontal location and internal pattern.
    out = [[0]*w for _ in range(h)]
    for color, cells, r0, r1, c0, c1 in comps:
        bh = r1-r0+1
        if r0 < h//2 and c0 < w*2//3:
            nr = 0
        else:
            nr = h-bh
        for y, x in cells:
            out[nr+y-r0][x] = color
    return out
